// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ScoreEditRequest) predicate.ScoreEditRequest {
	return predicate.ScoreEditRequest(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ScoreEditRequest) predicate.ScoreEditRequest {
	return predicate.ScoreEditRequest(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ScoreEditRequest) predicate.ScoreEditRequest {
	return predicate.ScoreEditRequest(sql.NotPredicates(p))
}
